) VALUES (
  'bulk_1788533434677_461_nuq6', '-P0gtN5LKh3VGGM07Vl8', 'bulk_1788533434677_461', 'Adel Osman', '', 'شركة ابناء الصاوي لتجارة المواد الغذائية بالجملة', 'shrka-abna-alsawy-ltgara-almwad-alghzayya-balgmla', 5, 'بجد ناس في منتهى الذوق والأمانة، وخدمة بيع المواد الغذائية بالجملة عندهم ممتازة ومفيهاش أي غلطة.', 1, 0, 1775448780682, 1775448780682
);

